parameters.jsCode:
// The API groups its answer by result date:
//   { data: { "2026-09-07": [ { finCode, compName, nseSymbol, bseSymbol, ... } ] } }
// Flatten that to one item per stock and keep both symbols: the dump asks NSE
// tools for the NSE ticker and BSE technicals for the BSE one, so they are
// carried separately rather than collapsed into a single "symbol".
//
// Both arrive with the trading *series* suffix - DHTL-SM (SME board),
// KOTYARK-BE (book entry), also -BZ / -BL / -ST / -IL / -RT. screener.in and
// Yahoo know the bare ticker only: /company/DHTL-SM/ is a 404 and /company/DHTL/
// is not, so the suffix comes off before anything is looked up.
const SERIES = /-(SM|ST|BE|BZ|BL|IL|RT|GB|GS|MF|IV|EQ|N[0-9]|W[0-9]|Y[0-9])$/i;

// Only a symbol matching this may reach the shell in the next node.
const SAFE = /^[A-Za-z0-9][A-Za-z0-9&.\-]{0,30}$/;
const clean = (v) => String(v ?? '').trim().replace(SERIES, '').toUpperCase();

const runId = new Date().toISOString().replace(/[-:]/g, '').replace(/\..+$/, 'Z');
const out = [];

const dud = (reason, payload) => ({ json: {
  runId, usable: false, skipReason: reason,
  company: null, symbol: null, nseSymbol: null, bseSymbol: null, rawSymbol: null,
  exchange: null, finCode: null, resultDate: null, details: null, apiRecord: payload,
} });

for (const item of $input.all()) {
  // fullResponse is on, so the document is under body and the status is visible.
  const status = item.json?.statusCode ?? null;
  const body = item.json?.body ?? item.json ?? {};
  const buckets = body?.data ?? null;

  if (status !== null && (status < 200 || status >= 300)) {
    out.push(dud('the upcoming-results API answered HTTP ' + status,
      { statusCode: status, body: JSON.stringify(body).slice(0, 1000) }));
    continue;
  }
  if (!buckets || typeof buckets !== 'object') {
    out.push(dud('the upcoming-results API returned no data object',
      { statusCode: status, body: JSON.stringify(body).slice(0, 1000) }));
    continue;
  }

  for (const [resultDate, rows] of Object.entries(buckets)) {
    for (const row of Array.isArray(rows) ? rows : []) {
      const nse = clean(row.nseSymbol);
      const bse = clean(row.bseSymbol);
      // screener.in is looked up by ticker; either listing resolves the company,
      // so NSE is preferred and BSE is the fallback identifier.
      const symbol = SAFE.test(nse) ? nse : (SAFE.test(bse) ? bse : '');
      const usable = Boolean(symbol);
      const rawNse = String(row.nseSymbol ?? '').trim();
      const rawBse = String(row.bseSymbol ?? '').trim();

      out.push({ json: {
        runId,
        resultDate,
        finCode: row.finCode ?? null,
        company: row.compName ?? null,
        symbol,                                        // screener identifier
        nseSymbol: SAFE.test(nse) ? nse : '',          // nse_* tools + .NS technicals
        bseSymbol: SAFE.test(bse) ? bse : '',          // .BO technicals
        rawSymbol: rawNse || rawBse || null,           // what the API actually said
        exchange: SAFE.test(nse) ? 'NSE' : (SAFE.test(bse) ? 'BSE' : null),
        details: String(row.details ?? '').trim() || null,
        usable,
        skipReason: usable ? null
          : (rawNse || rawBse
              ? '"' + (rawNse || rawBse) + '" does not reduce to a plain ticker'
              : 'the record carries no nseSymbol or bseSymbol'),
        // kept whole so a failure can be replayed against the exact input
        apiRecord: row,
      } });
    }
  }
}

if (out.length === 0) out.push(dud('the upcoming-results API listed no stocks', null));
return out;

parameters.command:
=# The full screener dump for one stock: 19 tools/call requests, printed as
# the same Markdown the manual node -e one-liner produces. The next node
# turns that document into JSON and the one after it looks for the column.
#
# ID   -> screener.in identifier (NSE ticker, else BSE)
# NSE  -> nse_get_* tools and the .NS technicals
# BSE  -> the .BO technicals
#
# The script is inlined with node -e and therefore lives inside a shell
# single-quoted string - it deliberately contains no single quote of its own.
# Values arrive as environment variables rather than being spliced into the
# source, and the flatten step has already restricted them to [A-Za-z0-9&.-].
# ID is empty for a stock with no usable ticker; the script says so rather
# than querying junk. It never exits non-zero.

ID="{{ $json.usable ? $json.symbol : "" }}" \
NSE_SYM="{{ $json.nseSymbol }}" \
BSE_SYM="{{ $json.bseSymbol }}" \
FIN_CODE="{{ $json.finCode }}" \
MCP_ENDPOINT="http://127.0.0.1:3123/mcp" \
MCP_TIMEOUT_MS=30000 \
node -e 'const ID = process.env.ID || "";
const NSE = process.env.NSE_SYM || ID;
const BSE = process.env.BSE_SYM || ID;
const FIN = process.env.FIN_CODE || "";
const CONS = process.env.CONSOLIDATED !== "0";
const ENDPOINT = process.env.MCP_ENDPOINT || "http://127.0.0.1:3123/mcp";
const TIMEOUT = Number(process.env.MCP_TIMEOUT_MS || 30000);
const RULE = "-".repeat(72);
const STMTS = ["quarters", "profit-loss", "balance-sheet", "cash-flow", "ratios"];
const TECH = [["RSI", 14], ["SMA", 50], ["EMA", 200], ["MACD", 0]];
const JOBS = [
  ["SEARCH MATCH", "screener_search_companies", { query: ID }],
  ["COMPANY OVERVIEW", "screener_get_company_overview", { identifier: ID, consolidated: CONS }],
  ...STMTS.map((s) => [s.toUpperCase(), "screener_get_financial_statement", { identifier: ID, statement: s, consolidated: CONS }]),
  ["PEER COMPARISON", "screener_get_peer_comparison", { identifier: ID, consolidated: CONS }],
  ["NSE LIVE QUOTE", "nse_get_quote", { symbol: NSE }],
  ["NSE ANNOUNCEMENTS", "nse_get_announcements", { symbol: NSE, limit: 10 }],
  ["NSE CORP ACTIONS", "nse_get_corporate_actions", { symbol: NSE, limit: 10 }],
  // NSE technicals read <nseSymbol>.NS and BSE technicals <bseSymbol>.BO, so the
  // two symbols the API gives are used where each one actually applies.
  ...[["NSE", NSE], ["BSE", BSE]].flatMap(([ex, sym]) =>
    TECH.map(([ind, tp]) => [
      ind + (tp ? " " + tp : "") + " daily [" + ex + "]",
      "technical_get_indicator",
      Object.assign({ ticker: sym, exchange: ex, indicator: ind, interval: "daily", limit: 5 }, tp ? { time_period: tp } : {}),
    ])
  ),
];

function parseBody(b) {
  const t = b.trim();
  if (t.charAt(0) === "{") return JSON.parse(t);
  const lines = t.split(/\r?\n/).filter((x) => x.indexOf("data:") === 0);
  const last = lines[lines.length - 1];
  if (!last) throw new Error("unparseable response: " + t.slice(0, 200));
  return JSON.parse(last.slice(5).trim());
}

function render(d) {
  if (d.error) return "RPC ERROR: " + JSON.stringify(d.error);
  const r = d.result || {};
  const c = r.content;
  if (!Array.isArray(c)) return JSON.stringify(r, null, 2);
  const text = c.map((x) => (x.text === undefined ? JSON.stringify(x) : x.text)).join("\n");
  return r.isError ? "TOOL ERROR: " + text : text;
}

const call = (name, args, id) => {
  const ac = new AbortController();
  const timer = setTimeout(() => ac.abort(), TIMEOUT);
  return fetch(ENDPOINT, {
    method: "POST",
    headers: { "Content-Type": "application/json", Accept: "application/json, text/event-stream", "Cache-Control": "no-cache" },
    body: JSON.stringify({ jsonrpc: "2.0", id: id, method: "tools/call", params: { name: name, arguments: args } }),
    signal: ac.signal,
  })
    .then((r) => r.text())
    .then((b) => render(parseBody(b)))
    .catch((e) => "REQUEST FAILED: " + (e && e.name === "AbortError" ? "timed out after " + TIMEOUT + "ms" : (e && e.message) || String(e)))
    .then((out) => { clearTimeout(timer); return out; });
};

(async () => {
  // A header the parser can key on, so the Markdown stays readable by a human
  // and machine-splittable at the same time.
  console.log("=".repeat(72));
  console.log("FULL DUMP  |  " + ID + "  |  nse=" + NSE + "  bse=" + BSE + "  finCode=" + FIN);
  console.log("GENERATED  |  " + new Date().toISOString());
  console.log("=".repeat(72));

  if (!ID) {
    console.log("\nDUMP ERROR: no usable symbol was supplied for this stock");
    return;
  }

  for (let i = 0; i < JOBS.length; i++) {
    const job = JOBS[i];
    const text = await call(job[1], job[2], i + 1);
    // "## <LABEL>   [<tool>]" - three spaces before the bracket. A tool answer
    // carries headings of its own (## Quarterly Results) but never the bracket,
    // which is what lets the parser tell a job header from section markup.
    console.log("\n\n" + RULE);
    console.log("## " + job[0] + "   [" + job[1] + "]");
    console.log(RULE + "\n");
    console.log(text);
  }
})();'

parameters.jsCode:
// Markdown dump -> JSON. One item in, one item out, per stock.
//
// The dump node prints the same human-readable Markdown the manual node -e
// one-liner does. Everything downstream needs it as data, so the whole document
// is turned into JSON here and nothing is thrown away: every job becomes an
// entry under `jobs`, every table becomes {columns, rows}, and the original text
// is kept alongside so a shape change upstream can never silently lose data.

// "## <LABEL>   [<tool>]" - three spaces, then the tool in brackets. Tool output
// carries headings of its own (## Quarterly Results) but never the bracket,
// which is what lets a job header be told apart from section markup.
const JOB_HEADER = /^##[ ](.+?)[ ]{3}\[([a-z_]+)\]$/;
const ERROR_PREFIX = /^(TOOL ERROR|RPC ERROR|REQUEST FAILED|DUMP ERROR):\s*/;

const splitRow = (line) => line.trim().replace(/^\|/, '').replace(/\|$/, '').split('|').map((c) => c.trim());
const isSeparator = (cells) => cells.length > 0 && cells.every((c) => /^:?-{2,}:?$/.test(c));

// "14.32" -> 14.32, "1,234" -> 1234; "17%", "₹ 382 Cr.", "-" stay as they are.
function coerce(value) {
  if (value === '' || value === '-' || value === '--') return null;
  if (/^-?\d{1,3}(,\d{2,3})*(\.\d+)?$/.test(value) || /^-?\d+(\.\d+)?$/.test(value)) {
    const n = Number(value.replace(/,/g, ''));
    if (Number.isFinite(n)) return n;
  }
  return value;
}

// A run of pipe rows -> { columns, rows: [{column: cell}], values: [[...]] }.
function readTable(lines, start) {
  const cells = [];
  let i = start;
  while (i < lines.length && lines[i].trim().startsWith('|')) { cells.push(splitRow(lines[i])); i += 1; }
  if (cells.length < 2 || !isSeparator(cells[1])) return null;
  const columns = cells[0];
  const body = cells.slice(2);
  return {
    end: i,
    table: {
      columns,
      rows: body.map((r) => Object.fromEntries(columns.map((c, n) => [c || 'col' + n, coerce(r[n] ?? '')]))),
      values: body.map((r) => r.map(coerce)),
    },
  };
}

// "- Market Cap: ₹ 382 Cr." is a field; "- Company has reduced debt." is not.
// The guard keeps a prose bullet that happens to contain a colon out of fields.
function asField(line) {
  const at = line.indexOf(':');
  if (at < 1 || at > 40) return null;
  const key = line.slice(0, at).trim();
  if (!key || /[.!?]\s/.test(key)) return null;
  return [key, line.slice(at + 1).trim()];
}

function parseMarkdown(body) {
  const lines = body.split(/\r?\n/);
  const sections = [];
  let current = { title: null, level: 0, tables: [], fields: {}, items: [], text: [] };

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const heading = /^(#{1,6})\s+(.*)$/.exec(line.trim());
    if (heading) {
      sections.push(current);
      current = { title: heading[2].trim(), level: heading[1].length, tables: [], fields: {}, items: [], text: [] };
      continue;
    }
    if (line.trim().startsWith('|')) {
      const read = readTable(lines, i);
      if (read) { current.tables.push(read.table); i = read.end - 1; continue; }
    }
    const bullet = /^\s*[-*]\s+(.*)$/.exec(line);
    if (bullet) {
      const field = asField(bullet[1]);
      if (field) current.fields[field[0]] = field[1];
      else current.items.push(bullet[1].trim());
      continue;
    }
    if (line.trim()) current.text.push(line.trim());
  }
  sections.push(current);

  const kept = sections.filter((s) => s.title || s.tables.length || s.items.length || Object.keys(s.fields).length || s.text.length);
  return kept.map((s) => ({ ...s, text: s.text.join('\n') }));
}

// --------------------------------------------------------------------------
const out = [];

for (const item of $input.all()) {
  const stock = $('Flatten Upcoming Results').all()[out.length]?.json ?? {};
  const stdout = String(item.json?.stdout ?? '');
  const who = {
    runId: stock.runId ?? null,
    company: stock.company ?? null,
    symbol: stock.symbol ?? null,
    nseSymbol: stock.nseSymbol ?? null,
    bseSymbol: stock.bseSymbol ?? null,
    rawSymbol: stock.rawSymbol ?? null,
    finCode: stock.finCode ?? null,
    resultDate: stock.resultDate ?? null,
    usable: stock.usable !== false,
    skipReason: stock.skipReason ?? null,
    apiRecord: stock.apiRecord ?? null,
  };

  if (!stdout.trim()) {
    out.push({ json: { ...who, ok: false, stage: 'mcp-query',
      error: 'the dump printed nothing (exit ' + (item.json?.exitCode ?? '?') + ')',
      stderr: String(item.json?.stderr ?? '').slice(-800),
      jobs: {}, columns: [], markdown: '' } });
    continue;
  }

  // --- split the document into its jobs ---------------------------------
  const lines = stdout.split(/\r?\n/);
  const jobs = {};
  const order = [];
  let label = null, tool = null, buffer = [];

  const flush = () => {
    if (label === null) return;
    const body = buffer.join('\n').trim();
    const err = ERROR_PREFIX.exec(body);
    const job = { tool, ok: !err, error: err ? body.slice(err[0].length).split('\n')[0] : null, raw: body };
    if (!err && body) {
      if (body.charAt(0) === '{' || body.charAt(0) === '[') {
        try { job.data = JSON.parse(body); } catch (e) { job.sections = parseMarkdown(body); }
      } else {
        job.sections = parseMarkdown(body);
      }
    }
    if (job.sections) {
      job.tables = job.sections.flatMap((s) => s.tables);
      job.fields = Object.assign({}, ...job.sections.map((s) => s.fields));
    }
    jobs[label] = job;
    order.push(label);
  };

  let generatedAt = null;
  for (const line of lines) {
    const header = JOB_HEADER.exec(line.trim());
    if (header) { flush(); label = header[1].trim(); tool = header[2]; buffer = []; continue; }
    if (label === null) {
      const gen = /^GENERATED\s+\|\s+(.+)$/.exec(line.trim());
      if (gen) generatedAt = gen[1].trim();
      continue; // banner
    }
    if (/^-{20,}$/.test(line.trim())) continue; // the rule under a job header
    buffer.push(line);
  }
  flush();

  // --- every column the dump produced, anywhere --------------------------
  const columns = [];
  const seen = new Set();
  for (const name of order) {
    for (const table of jobs[name].tables ?? []) {
      for (const col of table.columns) {
        if (!col || seen.has(col)) continue;
        seen.add(col);
        columns.push(col);
      }
    }
  }

  const failed = order.filter((n) => !jobs[n].ok);
  out.push({ json: { ...who,
    ok: order.length > 0,
    generatedAt,
    jobCount: order.length,
    jobsFailed: failed.length,
    failedJobs: failed,
    jobs,
    columns,
    markdown: stdout,
  } });
}

return out;

// The gate: a stock's dump is returned only when the target column actually
// appears somewhere in it. Runs once for all items and returns a single item,
// because the log writer downstream must fire once per run, not once per stock.
//
// >>> The one line to change when the quarter rolls over: <<<
const TARGET_PERIOD = 'Sep 2026';

const parsed = $input.all().map((i) => i.json);
const ts = new Date().toISOString();
const runId = parsed[0]?.runId ?? ts.replace(/[-:]/g, '').replace(/\..+$/, 'Z');

// "Sept 2026" and " sep 2026 " name the same column as "Sep 2026".
const key = (p) => String(p).replace(/\s+/g, ' ').trim().toLowerCase().replace(/^sept\b/, 'sep');
const TARGET = key(TARGET_PERIOD);

// Every table in every job is searched, not just the quarterly one - the column
// is the signal, and whichever statement carries it is a real hit.
function findColumn(jobs) {
  const hits = [];
  for (const [label, job] of Object.entries(jobs ?? {})) {
    (job.tables ?? []).forEach((table, index) => {
      for (const column of table.columns ?? []) {
        if (key(column) === TARGET) {
          hits.push({ job: label, tool: job.tool, table: index, column });
        }
      }
    });
  }
  return hits;
}

const qualified = [];
const failures = [];

for (const stock of parsed) {
  const who = {
    runId,
    company: stock.company,
    symbol: stock.symbol || null,
    nseSymbol: stock.nseSymbol || null,
    bseSymbol: stock.bseSymbol || null,
    rawSymbol: stock.rawSymbol,
    finCode: stock.finCode,
    resultDate: stock.resultDate,
  };

  // 1. the symbol never made it to the MCP server
  if (stock.usable === false) {
    failures.push({ ts, event: 'skipped', stage: 'symbol', ...who,
      reason: stock.skipReason, error: null, payload: { apiRecord: stock.apiRecord } });
    continue;
  }

  // 2. the dump itself never produced a document
  if (!stock.ok) {
    failures.push({ ts, event: 'failed', stage: stock.stage || 'mcp-query', ...who,
      reason: 'the MCP dump produced no usable document',
      error: stock.error ?? null,
      payload: { stderr: stock.stderr ?? null, apiRecord: stock.apiRecord } });
    continue;
  }

  // 3. every single job in the dump errored - a dead endpoint or a bad ticker,
  //    not a stock that merely has not filed yet
  if (stock.jobsFailed === stock.jobCount) {
    failures.push({ ts, event: 'failed', stage: 'mcp-tool', ...who,
      reason: 'every job in the dump failed',
      error: stock.jobs?.[stock.failedJobs[0]]?.error ?? null,
      payload: { jobCount: stock.jobCount, failedJobs: stock.failedJobs, apiRecord: stock.apiRecord } });
    continue;
  }

  // 4. the gate
  const hits = findColumn(stock.jobs);
  if (hits.length === 0) {
    failures.push({ ts, event: 'not-qualified', stage: 'filter', ...who,
      reason: stock.columns.length === 0
        ? 'the dump produced no tables at all, so it cannot carry a "' + TARGET_PERIOD + '" column'
        : 'no table in the dump has a "' + TARGET_PERIOD + '" column',
      error: null,
      payload: { columns: stock.columns, jobCount: stock.jobCount,
        jobsFailed: stock.jobsFailed, failedJobs: stock.failedJobs, apiRecord: stock.apiRecord } });
    continue;
  }

  qualified.push({ ts, ...who,
    matchedColumn: hits[0].column,
    targetPeriod: TARGET_PERIOD,
    matchedIn: hits,
    generatedAt: stock.generatedAt,
    jobCount: stock.jobCount,
    jobsFailed: stock.jobsFailed,
    failedJobs: stock.failedJobs,
    columns: stock.columns,
    jobs: stock.jobs,        // the whole dump, as JSON
    markdown: stock.markdown, // and the document it was parsed from
  });
}

// --------------------------------------------------------------------------
// Log lines. The qualified log is deliberately slim - the dump itself travels
// in the workflow output, not into a file that grows every 5 minutes.
const qualifiedLog = qualified.map((q) => ({
  ts: q.ts, runId, event: 'qualified', company: q.company, symbol: q.symbol,
  nseSymbol: q.nseSymbol, bseSymbol: q.bseSymbol, rawSymbol: q.rawSymbol,
  finCode: q.finCode, resultDate: q.resultDate,
  matchedColumn: q.matchedColumn,
  matchedIn: q.matchedIn.map((h) => h.job),
  jobCount: q.jobCount, jobsFailed: q.jobsFailed,
}));

const count = (e) => failures.filter((f) => f.event === e).length;
const summary = {
  ts, runId, targetPeriod: TARGET_PERIOD, checked: parsed.length,
  qualified: qualified.length, notQualified: count('not-qualified'),
  failed: count('failed'), skipped: count('skipped'),
};

const jsonl = (arr) => arr.map((o) => JSON.stringify(o)).join('\n');

return [{ json: {
  ok: true,
  ...summary,
  results: qualified,
  failures,
  logs: {
    qualifiedJsonl: jsonl(qualifiedLog),
    failuresJsonl: jsonl(failures),
    runJsonl: JSON.stringify(summary),
  },
} }];

// Fan the run back out to one item per qualifying stock.
//
// Read from the classifier rather than from $input: the log writer sits between
// them and Execute Command replaces the item with {exitCode, stdout, stderr}.
const run = $('Filter On Sep 2026 Column').first().json;
const logged = $input.first().json;

const base = {
  ok: true,
  runId: run.runId,
  ts: run.ts,
  targetPeriod: run.targetPeriod,
  logWritten: (logged?.exitCode ?? 0) === 0,
  logDir: '/home/node/.n8n/univest-results/logs',
};

// Nothing qualified is a normal outcome, not an error - most runs will land
// here until companies start filing the target quarter. The run summary still
// comes out so the caller can see what was checked.
if (!Array.isArray(run.results) || run.results.length === 0) {
  return [{ json: {
    ...base,
    qualified: 0,
    reason: 'no stock has a "' + run.targetPeriod + '" column yet',
    checked: run.checked,
    notQualified: run.notQualified,
    failed: run.failed,
    skipped: run.skipped,
    failures: run.failures,
  } }];
}

return run.results.map((stock) => ({ json: { ...base, ...stock } }));

// The MCP server never answered tools/list, so not one stock could be checked.
// That is a run-level failure and belongs in the same failures.jsonl as the
// per-stock ones, with the tail of the server log as the payload it failed for.
//
// The record is built here rather than inside an expression on the shell node:
// an object literal inside {{ }} is exactly the thing older n8n expression
// parsers get wrong, and a log writer that silently emits nothing is worse than
// no log writer at all.
const ts = new Date().toISOString();
const runId = ts.replace(/[-:]/g, '').replace(/\..+$/, 'Z');
const mcpLog = String($input.first().json?.stdout ?? '').slice(-1500);

const record = {
  ts,
  runId,
  event: 'failed',
  stage: 'mcp-health',
  company: null,
  symbol: null,
  rawSymbol: null,
  exchange: null,
  finCode: null,
  resultDate: null,
  reason: 'the screener MCP server did not answer tools/list, so no stock was checked',
  error: mcpLog.split('\n').filter(Boolean).slice(-1)[0] ?? 'no output from the MCP log',
  payload: { endpoint: 'http://127.0.0.1:3123/mcp', mcpLogTail: mcpLog },
};

return [{ json: {
  ok: false,
  ...record,
  logLine: JSON.stringify(record),
  runLine: JSON.stringify({ ts, runId, targetPeriod: null, checked: 0, qualified: 0, notQualified: 0, failed: 1, skipped: 0 }),
} }];

// Terminal state for the unhealthy branch: a parseable failure document, so a
// caller (or the supervisor) never has to tell "MCP was down" apart from
// "the workflow produced nothing".
const failure = $('Build Health Failure').first().json;
const written = $input.first().json;

return [{ json: {
  ok: false,
  stage: 'mcp-health',
  runId: failure.runId,
  ts: failure.ts,
  error: 'screener MCP server is not answering tools/list on http://127.0.0.1:3123/mcp',
  reason: failure.reason,
  mcpLogTail: failure.payload?.mcpLogTail ?? null,
  logWritten: (written?.exitCode ?? 0) === 0,
  logDir: '/home/node/.n8n/univest-results/logs',
} }];
